"""Distinct readings transcribed from printed 263–278 (IA n287–n302)."""
HASHKIVENU_SEAL = (
'וּשְׁמוֹר צֵאתֵֽנוּ וּבוֹאֵֽנוּ לְחַיִּים וּלְשָׁלוֹם, מֵעַתָּה וְעַד עוֹלָם, {reader}וּפְרוֹשׂ עָלֵֽינוּ סֻכַּת שְׁלוֹמֶֽךָ. בָּרוּךְ אַתָּה, יְיָ, הַפּוֹרֵשׂ סֻכַּת שָׁלוֹם עָלֵֽינוּ וְעַל כָּל עַמּוֹ יִשְׂרָאֵל, וְעַל יְרוּשָׁלָֽיִם.',
'Guard thou our going out and our coming in, for life and peace, henceforth and forever. Do thou spread over us thy shelter of peace. Blessed art thou, O Lord, who spreadest the shelter of peace over us and over all thy people Israel and over Jerusalem.')
VESHAMRU = [
('exodus/31/16','וְשָׁמְרוּ בְנֵי יִשְׂרָאֵל אֶת הַשַּׁבָּת, לַעֲשׂוֹת אֶת הַשַּׁבָּת לְדֹרֹתָם בְּרִית עוֹלָם.', 'The children of Israel shall keep the Sabbath, observing the Sabbath throughout their generations as an everlasting covenant.'),
('exodus/31/17','בֵּינִי וּבֵין בְּנֵי יִשְׂרָאֵל אוֹת הִיא לְעֹלָם, כִּי שֵׁשֶׁת יָמִים עָשָׂה יְיָ אֶת הַשָּׁמַֽיִם וְאֶת הָאָֽרֶץ, וּבַיּוֹם הַשְּׁבִיעִי שָׁבַת וַיִּנָּפַשׁ.', 'It is a sign between me and the children of Israel forever, that in six days the Lord made the heavens and the earth, and on the seventh day he ceased from work and rested.'),
]
VAYDABER = [('leviticus/23/44','וַיְדַבֵּר מֹשֶׁה אֶת מֹעֲדֵי יְיָ אֶל בְּנֵי יִשְׂרָאֵל.', 'Moses announced the festivals of the Lord to the children of Israel.')]
TIKU = [
('psalms/81/4','תִּקְעוּ בַחֹֽדֶשׁ שׁוֹפָר, בַּכֶּֽסֶה לְיוֹם חַגֵּֽנוּ.', 'Sound the Shofar at the new moon, at full moon for our feast-day.'),
('psalms/81/5','כִּי חֹק לְיִשְׂרָאֵל הוּא, מִשְׁפָּט לֵאלֹהֵי יַעֲקֹב.', 'This is a statute for Israel, an ordinance of the God of Jacob.'),
]
ATAH_KIDASHTA = (
'אַתָּה קִדַּֽשְׁתָּ אֶת יוֹם הַשְּׁבִיעִי לִשְׁמֶֽךָ, תַּכְלִית מַעֲשֵׂה שָׁמַֽיִם וָאָֽרֶץ, וּבֵרַכְתּוֹ מִכָּל הַיָּמִים וְקִדַּשְׁתּוֹ מִכָּל הַזְּמַנִּים, וְכֵן כָּתוּב בְּתוֹרָתֶֽךָ:',
'Thou hast sanctified to thyself the seventh day, marking the end of the creation of heaven and earth; thou hast blessed it above all days, and hallowed it above all festivals, as it is written in thy Torah:')
VAYKHULU = [
('genesis/2/1','וַיְכֻלּוּ הַשָּׁמַֽיִם וְהָאָֽרֶץ וְכָל צְבָאָם.', 'Thus the heavens and the earth were finished, and all their host.'),
('genesis/2/2','וַיְכַל אֱלֹהִים בַּיּוֹם הַשְּׁבִיעִי מְלַאכְתּוֹ אֲשֶׁר עָשָׂה, וַיִּשְׁבֹּת בַּיּוֹם הַשְּׁבִיעִי מִכָּל מְלַאכְתּוֹ אֲשֶׁר עָשָׂה.', 'By the seventh day God had completed his work which he had made, and he rested on the seventh day from all his work in which he had been engaged.'),
('genesis/2/3','וַיְבָֽרֶךְ אֱלֹהִים אֶת יוֹם הַשְּׁבִיעִי וַיְקַדֵּשׁ אֹתוֹ, כִּי בוֹ שָׁבַת מִכָּל מְלַאכְתּוֹ אֲשֶׁר בָּרָא אֱלֹהִים לַעֲשׂוֹת.', 'Then God blessed the seventh day and hallowed it, because on it he rested from all his work which he had created.'),
]
RETZEH_HE = 'אֱלֹהֵֽינוּ וֵאלֹהֵי אֲבוֹתֵֽינוּ, רְצֵה בִמְנוּחָתֵֽנוּ. קַדְּשֵֽׁנוּ בְּמִצְוֹתֶֽיךָ, וְתֵן חֶלְקֵֽנוּ בְּתוֹרָתֶֽךָ; שַׂבְּעֵֽנוּ מִטּוּבֶֽךָ, וְשַׂמְּחֵֽנוּ בִּישׁוּעָתֶֽךָ; וְטַהֵר לִבֵּֽנוּ לְעָבְדְּךָ בֶּאֱמֶת; וְהַנְחִילֵֽנוּ, יְיָ אֱלֹהֵֽינוּ, בְּאַהֲבָה וּבְרָצוֹן שַׁבַּת קָדְשֶֽׁךָ, וְיָנֽוּחוּ בָהּ יִשְׂרָאֵל מְקַדְּשֵׁי שְׁמֶֽךָ. בָּרוּךְ אַתָּה, יְיָ, מְקַדֵּשׁ הַשַּׁבָּת.'
RETZEH_EN = 'Our God and God of our fathers, be pleased with our rest. Sanctify us with thy commandments and grant us a share in thy Torah; satisfy us with thy goodness and gladden us with thy help; purify our heart to serve thee sincerely. In thy gracious love, Lord our God, grant that we keep thy holy Sabbath as a heritage; may Israel who sanctifies thy name rest on it. Blessed art thou, O Lord, who hallowest the Sabbath.'
MEIN_RETZEH_EN = 'Our God and God of our fathers, be pleased with our rest. Sanctify us with thy commandments and grant us a share in thy Torah; satisfy us with thy goodness and gladden us with thy deliverance; purify our heart to serve thee in truth; and, in thy gracious love, Lord our God, grant that we keep thy holy Sabbath as a heritage, and that Israel, who hallow thy name, may rest on it. Blessed art thou, O Lord, who hallowest the Sabbath.'
MEIN_OPENING = (
'בָּרוּךְ אַתָּה, יְיָ אֱלֹהֵֽינוּ וֵאלֹהֵי אֲבוֹתֵֽינוּ, אֱלֹהֵי אַבְרָהָם, אֱלֹהֵי יִצְחָק, וֵאלֹהֵי יַעֲקֹב, הָאֵל הַגָּדוֹל הַגִּבּוֹר וְהַנּוֹרָא, אֵל עֶלְיוֹן, קוֹנֵה שָׁמַֽיִם וָאָֽרֶץ.',
'Blessed art thou, Lord our God and God of our fathers, God of Abraham, God of Isaac and God of Jacob; great, mighty and revered God, supreme God, Master of heaven and earth.')
MAGEN_PREFIX = ('מָגֵן אָבוֹת בִּדְבָרוֹ, מְחַיֵּה מֵתִים בְּמַאֲמָרוֹ, ', 'He with his word was a shield to our fathers, and by his bidding he will revive the dead. He is the holy ')
MAGEN_REMAINDER = (
' הַקָּדוֹשׁ שֶׁאֵין כָּמֽוֹהוּ, הַמֵּנִֽיחַ לְעַמּוֹ בְּיוֹם שַׁבַּת קָדְשׁוֹ, כִּי בָם רָצָה לְהָנִֽיחַ לָהֶם; לְפָנָיו נַעֲבֹד בְּיִרְאָה וָפַֽחַד, וְנוֹדֶה לִשְׁמוֹ {pb:275}בְּכָל יוֹם תָּמִיד מֵעֵין הַבְּרָכוֹת. {reader}אֵל הַהוֹדָאוֹת, אֲדוֹן הַשָּׁלוֹם, מְקַדֵּשׁ הַשַּׁבָּת וּמְבָרֵךְ שְׁבִיעִי, וּמֵנִֽיחַ בִּקְדֻשָּׁה לְעַם מְדֻשְּׁנֵי עֹֽנֶג, זֵֽכֶר לְמַעֲשֵׂה בְרֵאשִׁית.',
', like whom there is none. He gives rest to his people on his holy Sabbath day, for he is pleased to grant them rest. Him we will serve with reverence and {pb:276}awe, and to his name we will give thanks every day, constantly, in the fitting form of blessings. He is the God to whom thanks are due, the Lord of peace, who hallows the Sabbath and blesses the seventh day, who gives sanctified rest to a joyful people—in remembrance of the creation.')
KIDDUSH = (
'בָּרוּךְ אַתָּה, יְיָ אֱלֹהֵֽינוּ, מֶֽלֶךְ הָעוֹלָם, אֲשֶׁר קִדְּשָֽׁנוּ בְּמִצְוֹתָיו וְרָֽצָה בָֽנוּ, וְשַׁבַּת קָדְשׁוֹ בְּאַהֲבָה וּבְרָצוֹן הִנְחִילָֽנוּ, זִכָּרוֹן לְמַעֲשֵׂה בְרֵאשִׁית; כִּי הוּא יוֹם תְּחִלָּה לְמִקְרָאֵי קֹֽדֶשׁ, זֵֽכֶר לִיצִיאַת מִצְרָֽיִם. כִּי בָֽנוּ בָחַֽרְתָּ וְאוֹתָֽנוּ קִדַּֽשְׁתָּ מִכָּל הָעַמִּים, וְשַׁבַּת קָדְשְׁךָ בְּאַהֲבָה וּבְרָצוֹן הִנְחַלְתָּֽנוּ. בָּרוּךְ אַתָּה, יְיָ, מְקַדֵּשׁ הַשַּׁבָּת.',
'Blessed art thou, Lord our God, King of the universe, who hast sanctified us with thy commandments and hast been pleased with us; thou hast graciously given us thy holy Sabbath as a heritage, in remembrance of the creation. The Sabbath is the first among the holy festivals which recall the exodus from Egypt. Indeed, thou hast chosen us and hallowed us above all nations, and hast graciously given us thy holy Sabbath as a heritage. Blessed art thou, O Lord, who hallowest the Sabbath.')
WINE = ('בָּרוּךְ אַתָּה, יְיָ אֱלֹהֵֽינוּ, מֶֽלֶךְ הָעוֹלָם, בּוֹרֵא פְּרִי הַגָּֽפֶן.', 'Blessed art thou, Lord our God, King of the universe, who createst the fruit of the vine.')
